  var labels = new StackPanel { VerticalAlignment = VerticalAlignment.Center }; var titleBlock = Text(title,16); titleBlock.Margin = new(0); labels.Children.Add(titleBlock); if (!string.IsNullOrEmpty(subtitle)) { var sub = Text(subtitle,13,true); sub.Margin = new(0,3,0,0); labels.Children.Add(sub); } Grid.SetColumn(labels,1); grid.Children.Add(labels);
