  Row(dictation,"\uE72E",C("settings.row.api_keys","API keys"),null,keyCount == 0 ? C("value.none","None") : C("settings.keys.set","%1$d set",keyCount),() => Navigate("keys"));
  Row(dictation,"\uE734",C("settings.row.cleanup","Clean up with AI"),null,S.UseCleanup ? C("value.on","On") : C("value.off","Off"),() => Navigate("cleanup"));
  Row(dictation,"\uE8D2",C("settings.row.writing_style","Writing style"),null,S.DefaultStyle.ToString(),() => Navigate("style"));
  Row(dictation,"\uE70F",C("settings.row.custom_words","Custom words"),null,C("settings.words.count","%1$d",S.CustomWords.Count),() => Navigate("words"));
